# Thread-safe task engine with fencing tokens for cancellation/restart/stale-publish handling.
import copy
import threading
import uuid


class Engine:
    def __init__(self):
        # OrderedDict preserves submission order: {task_id: task}
        self._tasks = {}
        self._order = []
        self._task_by_key = {}  # active tasks: (owner, key) -> task_id
        self._lock = threading.Lock()
        self._next_id = 0

    # ---------- submit ----------
    def submit(self, owner, key):
        with self._lock:
            existing = self._task_by_key.get((owner, key))
            if existing is not None:
                return existing  # duplicate active key returns same id
            tid = 1000 + self._next_id
            self._next_id += 1
            task = {
                'owner': owner,
                'key': key,
                'task_id': tid,
                'state': 'queued',  # queued | running | terminal
                'lease_token': None,
                'lease_time': None,
                'status': 'pending',
                'result': None,
            }
            self._tasks[tid] = task
            self._order.append(tid)
            self._task_by_key[(owner, key)] = tid
            return tid

    # ---------- claim ----------
    def claim(self, worker, now, ttl):
        if isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or ttl <= 0:
            raise ValueError('ttl must be positive')
        if now is not None and (isinstance(now, bool) or not isinstance(now, (int, float))):
            raise ValueError('now must be a number or None')
        with self._lock:
            chosen = None
            # Queued tasks are eligible in insertion order.
            for tid in self._order:
                task = self._tasks[tid]
                if task['state'] == 'queued':
                    chosen = tid
                    break
            if chosen is None:
                # Running tasks become eligible when unexpired lease is missing or expired.
                for tid in self._order:
                    task = self._tasks[tid]
                    if task['state'] != 'running':
                        continue
                    if task['lease_token'] is None:
                        chosen = tid
                        break
                    if now is not None and task['lease_time'] is not None:
                        if task['lease_time'] + ttl <= now:
                            chosen = tid
                            break
            if chosen is None:
                return None
            task = self._tasks[chosen]
            token = str(uuid.uuid4())
            task['lease_token'] = token
            task['lease_time'] = now
            return {'task_id': chosen, 'worker': worker, 'token': token, 'owner': task['owner']}

    # ---------- cancel ----------
    def cancel(self, owner, task_id):
        with self._lock:
            task = self._tasks.get(task_id)
            if task is None:
                return False
            if task['state'] == 'terminal':
                return False
            if task['owner'] != owner:
                raise PermissionError('permission denied')
            task['state'] = 'terminal'
            task['status'] = 'cancelled'
            self._task_by_key.pop((task['owner'], task['key']), None)
            return True

    # ---------- publish ----------
    def publish(self, lease, now, result):
        if lease is None:
            return False
        with self._lock:
            task = self._tasks.get(lease.get('task_id'))
            if task is None or task['state'] != 'running':
                return False
            if task['lease_token'] != str(lease.get('token')):
                return False
            ttl = lease.get('ttl')
            if ttl is not None and now is not None and task['lease_time'] is not None:
                if task['lease_time'] + ttl <= now:
                    return False
            if task['status'] == 'completed' or task['result'] is not None:
                return False
            task['status'] = 'completed'
            task['result'] = copy.deepcopy(result)
            self._task_by_key.pop((task['owner'], task['key']), None)
            return True

    # ---------- results ----------
    def results(self, owner):
        with self._lock:
            out = []
            for tid in self._order:
                task = self._tasks[tid]
                if (task['owner'] == owner and task['state'] == 'terminal'
                        and task['status'] == 'completed' and task['result'] is not None):
                    out.append(copy.deepcopy(task['result']))
            return out
